import numpy as np


def v_from_q(q_values: np.ndarray, policy: np.ndarray) -> np.ndarray:
    q = np.asarray(q_values, dtype=float)
    pi = np.asarray(policy, dtype=float)
    if q.ndim != 2 or pi.shape != q.shape:
        raise ValueError("q_values and policy must have the same 2D shape")
    if np.any(pi < 0.0) or not np.allclose(pi.sum(axis=1), 1.0):
        raise ValueError("each policy row must be a probability distribution")
    return np.sum(pi * q, axis=1)


def advantage(q_values: np.ndarray, policy: np.ndarray) -> np.ndarray:
    q = np.asarray(q_values, dtype=float)
    return q - v_from_q(q, policy)[:, None]
```

The extra axis turns the state-value vector into a column, allowing one $V(s)$ to be subtracted from every action in that state.

