import math


def td_target(reward, next_value, gamma, *, terminated, truncated=False):
    if not math.isfinite(reward) or not math.isfinite(gamma):
        raise ValueError("reward and gamma must be finite")
    if not 0.0 <= gamma <= 1.0:
        raise ValueError("gamma must be in [0, 1]")
    if not isinstance(terminated, bool) or not isinstance(truncated, bool):
        raise TypeError("flags must be boolean")
    if terminated:
        return float(reward)
    if not math.isfinite(next_value):
        raise ValueError("next_value must be finite for a non-terminal target")
    return float(reward + gamma * next_value)


def n_step_target(rewards, bootstrap_value, gamma, *, terminated_at_end):
    if not math.isfinite(gamma) or not 0.0 <= gamma <= 1.0:
        raise ValueError("gamma must be finite and in [0, 1]")
    if not isinstance(terminated_at_end, bool):
        raise TypeError("terminated_at_end must be boolean")
    total = 0.0
    discount = 1.0
    for reward in rewards:
        reward = float(reward)
        if not math.isfinite(reward):
            raise ValueError("rewards must be finite")
        total += discount * reward
        discount *= gamma
    if terminated_at_end:
        return total
    if not math.isfinite(bootstrap_value):
        raise ValueError("bootstrap_value must be finite for a non-terminal target")
    return total + discount * float(bootstrap_value)
```

`truncated` is retained in the interface to make the stopping reason visible. The bootstrap mask is controlled by task termination.

