import numpy as np


def q_learning_target(reward, next_q_values, gamma, *, terminated):
    if terminated:
        return float(reward)
    q_next = np.asarray(next_q_values, dtype=float)
    if q_next.ndim != 1 or q_next.size == 0:
        raise ValueError("next_q_values must be a non-empty vector")
    return float(reward + gamma * np.max(q_next))


def sarsa_target(reward, next_q_values, next_action, gamma, *, terminated):
    if terminated:
        return float(reward)
    q_next = np.asarray(next_q_values, dtype=float)
    if q_next.ndim != 1 or not 0 <= next_action < q_next.size:
        raise ValueError("invalid next action")
    return float(reward + gamma * q_next[next_action])
```

The full SARSA loop must choose `next_action` using the same behavior policy that will act on the next transition.

