import numpy as np


def double_q_target(reward, selector_q, evaluator_q, gamma, *, terminated):
    if terminated:
        return float(reward)
    selector = np.asarray(selector_q, dtype=float)
    evaluator = np.asarray(evaluator_q, dtype=float)
    if selector.ndim != 1 or evaluator.shape != selector.shape or selector.size == 0:
        raise ValueError("Q vectors must be non-empty and have the same shape")
    selected = int(np.argmax(selector))
    return float(reward + gamma * evaluator[selected])
```

Taking `np.max(evaluator)` would let the second table choose a different action. Double Q-learning evaluates the action selected by the first table.
